insert into public.languages(code,name) values('en','English'),('zu','isiZulu'),('xh','isiXhosa'),('nso','Sepedi'),('tn','Setswana'),('af','Afrikaans'),('st','Sesotho'),('ts','Xitsonga'),('ss','siSwati'),('ve','Tshivenda'),('nd','isiNdebele') on conflict(code) do nothing;
insert into public.cultures(name,description) values('Zulu','Zulu storytelling traditions and language'),('Xhosa','Xhosa language and oral tradition'),('Sotho','Southern Sotho and related storytelling traditions'),('Tswana','Setswana language and oral traditions'),('Tsonga','Tsonga language and cultural stories'),('Venda','Tshivenda language and oral traditions') on conflict(name) do nothing;
insert into public.fire_circles(title,description,starts_at,status,capacity) values('Saturday Family Fire','A gentle pilot circle for families to listen together.',now()+interval '3 days','scheduled',40) on conflict do nothing;
